#include "erl/Persistence.h"
#include "erl/System.h"
#include <cstdint>
#include <filesystem>
#include <fstream>
namespace erl { namespace { void ws(std::fstream&f,const std::string&s){auto n=(std::uint32_t)s.size();f.write((char*)&n,sizeof n).write(s.data(),n);} bool rs(std::fstream&f,std::string&s){std::uint32_t n=0;if(!f.read((char*)&n,sizeof n)||n>1000000)return false;s.assign(n,'\0');return(bool)f.read(s.data(),n);} template<class T>void w(std::fstream&f,const T&v){f.write((char*)&v,sizeof v);} template<class T>bool r(std::fstream&f,T&v){return(bool)f.read((char*)&v,sizeof v);} }
bool BinaryPersistence::save(const ReliefHub&h,const std::string&p,std::string&e){std::string t=p+".tmp";std::fstream f(t,std::ios::binary|std::ios::out|std::ios::trunc);if(!f){e="Unable to open temporary persistence file";return false;}std::uint32_t magic=0x45524C31,n=0x0;w(f,magic);w(f,(n=(std::uint32_t)h.depots_.size()));for(const auto&[id,d]:h.depots_){ws(f,d.id());ws(f,d.name());w(f,d.capacityKg());auto c=d.inventory();w(f,(n=(std::uint32_t)c.size()));for(const auto&i:c){ws(f,i.id());ws(f,i.category());w(f,i.quantity());w(f,i.unitWeightKg());w(f,i.priority());}}w(f,(n=(std::uint32_t)h.vehicles_.size()));for(const auto&[id,v]:h.vehicles_){ws(f,v->kind());ws(f,v->id());ws(f,v->agency());w(f,v->capacityKg());w(f,v->fuelLitres());w(f,(int)v->status());auto c=v->beacon().coordinate();w(f,c.latitude);w(f,c.longitude);}w(f,(n=(std::uint32_t)h.missions_.size()));for(const auto&m:h.missions_){ws(f,m.id());w(f,(int)m.type());ws(f,m.originDepot());ws(f,m.destination());ws(f,m.cargoId());w(f,m.quantity());w(f,m.distanceKm());ws(f,m.corridor());w(f,m.priority());w(f,(int)m.status());ws(f,m.assignedVehicleId());w(f,m.critical_);}w(f,(n=(std::uint32_t)h.history_.size()));for(const auto&s:h.history_)ws(f,s);f.flush();if(!f){e="Failed while writing persistence file";return false;}f.close();std::error_code ec;std::filesystem::rename(t,p,ec);if(ec){ec.clear();auto b=p+".bak";std::filesystem::remove(b,ec);ec.clear();if(std::filesystem::exists(p)){std::filesystem::rename(p,b,ec);if(ec){e=ec.message();return false;}}std::filesystem::rename(t,p,ec);if(ec){std::error_code x;if(std::filesystem::exists(b))std::filesystem::rename(b,p,x);e=ec.message();return false;}std::filesystem::remove(b,ec);}return true;}
bool BinaryPersistence::load(ReliefHub&h,const std::string&p,std::string&e){std::fstream f(p,std::ios::binary|std::ios::in);if(!f){e="Persistence file does not exist";return false;}std::uint32_t magic=0,n=0;if(!r(f,magic)||magic!=0x45524C31){e="Invalid ERL-HUB persistence header";return false;}ReliefHub x;if(!r(f,n)||n>10000){e="Invalid depot count";return false;}for(std::uint32_t a=0;a<n;++a){std::string id,name;if(!rs(f,id)||!rs(f,name))return false;double cap=0; if(!r(f,cap))return false;DistributionDepot d(id,name,cap);std::uint32_t c=0;if(!r(f,c)||c>100000)return false;for(std::uint32_t b=0;b<c;++b){std::string i,k;int q,pv;double wv;if(!rs(f,i)||!rs(f,k)||!r(f,q)||!r(f,wv)||!r(f,pv))return false;d+=ReliefCargo(i,k,q,wv,pv);}x.depots_.emplace(id,std::move(d));}if(!r(f,n)||n>10000)return false;for(std::uint32_t a=0;a<n;++a){std::string k,id,ag;double cap,fuel,la,lo;int st;if(!rs(f,k)||!rs(f,id)||!rs(f,ag)||!r(f,cap)||!r(f,fuel)||!r(f,st)||!r(f,la)||!r(f,lo))return false;auto v=makeVehicle(k,id,ag,cap,fuel,{la,lo});v->setFuelLitres(fuel);v->setStatus((VehicleStatus)st);x.vehicles_.emplace(id,std::move(v));}if(!r(f,n)||n>100000)return false;for(std::uint32_t a=0;a<n;++a){std::string id,o,d,c,co,as;int ty,q,pr,st;double di;bool cr;if(!rs(f,id)||!r(f,ty)||!rs(f,o)||!rs(f,d)||!rs(f,c)||!r(f,q)||!r(f,di)||!rs(f,co)||!r(f,pr)||!r(f,st)||!rs(f,as)||!r(f,cr))return false;ReliefMission m(id,(MissionType)ty,o,d,c,q,di,co,pr);m.status_=(MissionStatus)st;m.assignedVehicleId_=as;m.critical_=cr;x.missions_.push_back(std::move(m));}if(!r(f,n)||n>100000)return false;for(std::uint32_t a=0;a<n;++a){std::string s;if(!rs(f,s))return false;x.history_.push_back(std::move(s));}h=std::move(x);return true;}
}

